export function tFactory(lang) {
  return function t(key, vars) {
    const entry = TR[key];
    let str = (entry && (entry[lang] || entry.en)) || key;
    if (vars) Object.keys(vars).forEach((k) => { str = str.split(`{${k}}`).join(vars[k]); });
    return str;
  };
}
